    // lat half-width: 5 mas in lat = same rad
    double lonP[4]={cx+h, cx+h, cx-h, cx-h};
    double latP[4]={cy+h, cy+h, cy-h, cy-h};
    // Q: offset by 5 mas east (half of P width)
    double lonQ[4]={cx+3*h, cx+3*h, cx+h, cx+h};
    double latQ[4]={cy+h, cy+h, cy-h, cy-h};
    double ovP = computeOverlap(lonP,latP,lonP,latP,0,1,&r);
    double ov  = computeOverlap(lonP,latP,lonQ,latQ,0,1,&r);
