#include <stdio.h>
#include <math.h>
#include "overlapArea.h"
// High-accuracy reference: fan triangulation with Oosterom-Strackee in long double
// on the *clipped* polygon. But we need the clipped polygon. Instead, use a
// fine Monte Carlo with a deterministic Halton-ish grid in the tangent plane for
// a rectangle overlap, which is essentially exact for axis-aligned boxes.
// For a half-offset in lon only:
static double ref_frac(double w_r, double dx_r){
  // two squares of side w_r (rad, in a tangent plane ~ flat), Q offset by dx_r in x
  // overlap width = w_r - dx_r (if 0<dx<w), fraction = (w-dx)/w
  if(dx_r<=0||dx_r>=w_r) return 0.;
  return (w_r-dx_r)/w_r;
}
int main(void){
  double d=M_PI/180.0;
  double wmax_deg=2.5e-4/(d*0.70710678);
  printf("%10s %12s %12s %12s\n","w(deg)","combined","ref","rel-err");
  for(int k=0;k<14;k++){
    double w=wmax_deg*(0.05+k*0.08); // 0.005 .. ~1.15 * wmax (crossing threshold)
    double hw=0.5*w*d;
    double ilon[4]={-hw, hw, hw, -hw};
    double ilat[4]={-hw, -hw, hw, hw};
    double dx=0.5*w*d; // half offset
    double olon[4]={-hw+dx, hw+dx, hw+dx, -hw+dx};
    double olat[4]={-hw, -hw, hw, hw};
    double r;
    double self=computeOverlap(ilon,ilat,ilon,ilat,0,1,&r);
    double ov=computeOverlap(ilon,ilat,olon,olat,0,1,&r);
    double combo = self>0 ? ov/self : 0.;
    double ref=ref_frac(w*d, dx);
    printf("%10.4f %12.6f %12.6f %12.2e\n", w, combo, ref, fabs(combo-ref)/ref);
  }
  return 0;
}
